-- Global One Foundation School Management System: MySQL 8 / MariaDB 10.5+ schema (InnoDB, utf8mb4)
CREATE TABLE IF NOT EXISTS settings (k VARCHAR(50) PRIMARY KEY, v MEDIUMTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS classes (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(40) NOT NULL UNIQUE, sort_order INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS subjects (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(60) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS students (
  id INT AUTO_INCREMENT PRIMARY KEY,
  adm VARCHAR(20) NULL UNIQUE,                       -- G1S/YYYY/NNNN, assigned once, never changed
  name VARCHAR(100) NOT NULL, class_id INT NOT NULL,
  guardian VARCHAR(100) NOT NULL DEFAULT '', phone VARCHAR(15) NOT NULL DEFAULT '',
  gender ENUM('','Male','Female') NOT NULL DEFAULT '', dob DATE NULL, birth_cert VARCHAR(40) NOT NULL DEFAULT '',
  status VARCHAR(20) NOT NULL DEFAULT 'Active', caregiver VARCHAR(30) NOT NULL DEFAULT '',
  relationship VARCHAR(40) NOT NULL DEFAULT '', parent_status VARCHAR(30) NOT NULL DEFAULT '',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY ix_students_name (name), KEY ix_students_class (class_id), KEY ix_students_phone (phone),
  CONSTRAINT fk_students_class FOREIGN KEY (class_id) REFERENCES classes(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS admission_counter (id TINYINT PRIMARY KEY, n INT NOT NULL) ENGINE=InnoDB;
INSERT IGNORE INTO admission_counter (id, n) VALUES (1, 0);
CREATE TABLE IF NOT EXISTS users (
  id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL,
  email VARCHAR(120) NULL UNIQUE, phone VARCHAR(15) NULL UNIQUE, pw_hash VARCHAR(255) NOT NULL,
  role ENUM('Admin','Teacher','Staff','Parent') NOT NULL, status ENUM('active','pending') NOT NULL DEFAULT 'pending',
  student_id INT NULL, last_login_at DATETIME NULL, last_login_ip VARCHAR(45) NULL, created_at DATETIME NOT NULL,
  CONSTRAINT fk_users_student FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS auth_codes (user_id INT NOT NULL, kind VARCHAR(10) NOT NULL, code_hash CHAR(64) NOT NULL, expires_at DATETIME(3) NOT NULL, attempts INT NOT NULL DEFAULT 0, PRIMARY KEY (user_id, kind), CONSTRAINT fk_codes_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rate_limits (k VARCHAR(160) PRIMARY KEY, n INT NOT NULL, reset_at DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_log (id BIGINT AUTO_INCREMENT PRIMARY KEY, at DATETIME NOT NULL, actor_name VARCHAR(100) NOT NULL DEFAULT '', actor_role VARCHAR(20) NOT NULL DEFAULT '', action VARCHAR(60) NOT NULL, details VARCHAR(255) NOT NULL DEFAULT '-', ip VARCHAR(45) NOT NULL DEFAULT '', KEY ix_audit_at (at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS fee_structures (id INT AUTO_INCREMENT PRIMARY KEY, class_id INT NOT NULL, term VARCHAR(10) NOT NULL, year SMALLINT NOT NULL, amount DECIMAL(12,2) NOT NULL, UNIQUE KEY ux_fee (class_id, term, year), CONSTRAINT fk_fee_class FOREIGN KEY (class_id) REFERENCES classes(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payments (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, amount DECIMAL(12,2) NOT NULL, paid_on DATE NOT NULL, method VARCHAR(30) NOT NULL, ref VARCHAR(40) NOT NULL UNIQUE, created_by INT NULL, KEY ix_pay_student (student_id), KEY ix_pay_date (paid_on), CONSTRAINT fk_pay_student FOREIGN KEY (student_id) REFERENCES students(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS mpesa_pending (checkout_id VARCHAR(80) PRIMARY KEY, student_id INT NOT NULL, amount DECIMAL(12,2) NOT NULL, created_at DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inventory_categories (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(60) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS inventory_items (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, category_id INT NULL, location VARCHAR(80) NOT NULL DEFAULT '', qty INT NOT NULL DEFAULT 0, damaged INT NOT NULL DEFAULT 0, CONSTRAINT fk_inv_cat FOREIGN KEY (category_id) REFERENCES inventory_categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS announcements (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(150) NOT NULL, body TEXT NOT NULL, audience ENUM('All','Teachers','Parents') NOT NULL, by_name VARCHAR(100) NOT NULL, created_at DATETIME NOT NULL, total INT NOT NULL DEFAULT 0, delivered INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS announcement_reads (announcement_id INT NOT NULL, user_id INT NOT NULL, read_at DATETIME NOT NULL, PRIMARY KEY (announcement_id, user_id), CONSTRAINT fk_ar_a FOREIGN KEY (announcement_id) REFERENCES announcements(id) ON DELETE CASCADE, CONSTRAINT fk_ar_u FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS results (student_id INT NOT NULL, subject_id INT NOT NULL, year SMALLINT NOT NULL, term VARCHAR(10) NOT NULL, exam TINYINT NOT NULL, mark DECIMAL(5,2) NOT NULL, PRIMARY KEY (student_id, subject_id, year, term, exam), CONSTRAINT fk_res_s FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE, CONSTRAINT fk_res_sub FOREIGN KEY (subject_id) REFERENCES subjects(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS result_publications (class_id INT NOT NULL, year SMALLINT NOT NULL, term VARCHAR(10) NOT NULL, PRIMARY KEY (class_id, year, term), CONSTRAINT fk_pub_c FOREIGN KEY (class_id) REFERENCES classes(id) ON DELETE CASCADE) ENGINE=InnoDB;
